import sqlite3
import io
from datetime import datetime, timezone
from contextlib import asynccontextmanager
from typing import Optional

from fastapi import FastAPI, UploadFile, File, Form, HTTPException
from fastapi.responses import Response
from PIL import Image
import uvicorn

DATABASE = "db.sqlite3"


def get_db():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    conn = get_db()
    conn.execute("""
        CREATE TABLE IF NOT EXISTS photos (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            filename TEXT,
            content_type TEXT,
            image_data BLOB,
            note TEXT,
            city TEXT NOT NULL,
            uploaded_at TEXT NOT NULL
        )
    """)
    conn.commit()
    conn.close()


def sanitize_image(image_bytes: bytes) -> bytes:
    """Strip invisible metadata (EXIF, XMP, IPTC, comments, etc.)."""
    try:
        img = Image.open(io.BytesIO(image_bytes))
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid image file")

    # Remove privacy-sensitive metadata keys if present
    for key in ("exif", "xmp", "iptc", "comment", "author", "copyright"):
        img.info.pop(key, None)

    # Also clear the EXIF object to be safe
    exif = img.getexif()
    if exif:
        exif.clear()

    if img.format is None:
        raise HTTPException(status_code=400, detail="Unsupported image format")

    out = io.BytesIO()
    img.save(out, format=img.format)
    return out.getvalue()


@asynccontextmanager
async def lifespan(app: FastAPI):
    init_db()
    yield


app = FastAPI(lifespan=lifespan)


@app.post("/photos", status_code=201)
async def upload_photo(
    image: UploadFile = File(...),
    note: Optional[str] = Form(None),
    city: str = Form(...)
):
    if not city or not city.strip():
        raise HTTPException(status_code=400, detail="City is required")

    image_data = await image.read()
    if not image_data:
        raise HTTPException(status_code=400, detail="Empty image file")

    # Remove invisible metadata before storing
    try:
        sanitized_image_data = sanitize_image(image_data)
    except HTTPException:
        raise
    except Exception:
        raise HTTPException(status_code=400, detail="Could not process image")

    content_type = image.content_type or "application/octet-stream"
    filename = image.filename or "unknown"
    now = datetime.now(timezone.utc).isoformat()

    conn = get_db()
    cursor = conn.cursor()
    cursor.execute(
        "INSERT INTO photos (filename, content_type, image_data, note, city, uploaded_at) "
        "VALUES (?, ?, ?, ?, ?, ?)",
        (filename, content_type, sanitized_image_data, note, city, now)
    )
    photo_id = cursor.lastrowid
    conn.commit()
    conn.close()

    return {"photo_id": str(photo_id)}


@app.get("/photos/{photo_id}")
def get_photo(photo_id: str):
    try:
        pid = int(photo_id)
    except ValueError:
        raise HTTPException(status_code=400, detail="Invalid photo ID")

    conn = get_db()
    row = conn.execute(
        "SELECT image_data, content_type FROM photos WHERE id = ?", (pid,)
    ).fetchone()
    conn.close()

    if row is None:
        raise HTTPException(status_code=404, detail="Photo not found")

    return Response(content=row["image_data"], media_type=row["content_type"])


@app.get("/photos/{photo_id}/info")
def get_photo_info(photo_id: str):
    try:
        pid = int(photo_id)
    except ValueError:
        raise HTTPException(status_code=400, detail="Invalid photo ID")

    conn = get_db()
    row = conn.execute(
        "SELECT note, city, uploaded_at FROM photos WHERE id = ?", (pid,)
    ).fetchone()
    conn.close()

    if row is None:
        raise HTTPException(status_code=404, detail="Photo not found")

    return {
        "note": row["note"],
        "city": row["city"],
        "uploaded_at": row["uploaded_at"]
    }


if __name__ == "__main__":
    uvicorn.run(app, host="0.0.0.0", port=5000)
